// protobufjs's 64-bit read path in miniature -- the shape that made a
// compiled zapo decode EVERY uint64 field to 0.
//
// Transcribed from zapo's shipped node_modules/zapo-js/spec/proto/index.js
// (protobufjs 7, minified). Three files collapse into this one:
//
//   util/longbits.js
//     function o(e,t){this.lo=e>>>0,this.hi=t>>>0}
//     o.prototype.toNumber=function(e){...return this.lo+4294967296*this.hi}
//     o.prototype.toLong  =function(e){...{low:0|this.lo,high:0|this.hi,...}}
//
//   reader.js  (readLongVarint)
//     function p(){var e=new r(0,0),t=0;
//       ...e.lo=(e.lo|(127&this.buf[this.pos])<<7*t)>>>0...}
//
//   reader.js  (_configure -- the line that matters)
//     var t=o.Long?"toLong":"toNumber";
//     o.merge(s.prototype,{uint64:function(){return p.call(this)[t](!0)},...})
//
// That last line is an ELEMENT-spelled method call whose key is a closure
// string picked once, at configure time, from whether `long` is installed.
// JS's o[k](...) is Get(o, ToPropertyKey(k)) then Call WITH o BOUND, the
// same two steps as o.m(...). Answering it with a keyed read plus a
// receiverless call drops the receiver, and then:
//
//   toLong   reads this.lo -> undefined -> `0 | undefined`            -> 0
//   toNumber reads this.lo -> undefined -> `undefined + 4294967296*undefined` -> NaN
//
// One dropped receiver, two spellings, no diagnostic on either -- which is
// exactly what a compiled zapo printed (0) and what it printed before
// `long` was installed at all (NaN). readLongVarint itself is INNOCENT:
// `rawbits` below reads the same LongBits fields directly and they are
// correct on every payload.
"use strict";

function LB(lo, hi) {
    this.lo = lo >>> 0;
    this.hi = hi >>> 0;
}
LB.prototype.toNumber = function (u) {
    if (!u && this.hi >>> 31) {
        var t = 1 + ~this.lo >>> 0, n = ~this.hi >>> 0;
        return t || (n = n + 1 >>> 0), -(t + 4294967296 * n);
    }
    return this.lo + 4294967296 * this.hi;
};
LB.prototype.toLong = function (u) {
    return { low: 0 | this.lo, high: 0 | this.hi, unsigned: Boolean(u) };
};

function R(buf) {
    this.buf = buf;
    this.pos = 0;
    this.len = buf.length;
}

// readLongVarint, transcribed
function p() {
    var e = new LB(0, 0), t = 0;
    if (!(this.len - this.pos > 4)) {
        for (; t < 3; ++t) {
            if (this.pos >= this.len) throw Error("index out of range");
            if (e.lo = (e.lo | (127 & this.buf[this.pos]) << 7 * t) >>> 0, this.buf[this.pos++] < 128) return e;
        }
        return e.lo = (e.lo | (127 & this.buf[this.pos++]) << 7 * t) >>> 0, e;
    }
    for (; t < 4; ++t) if (e.lo = (e.lo | (127 & this.buf[this.pos]) << 7 * t) >>> 0, this.buf[this.pos++] < 128) return e;
    if (e.lo = (e.lo | (127 & this.buf[this.pos]) << 28) >>> 0, e.hi = (e.hi | (127 & this.buf[this.pos]) >> 4) >>> 0, this.buf[this.pos++] < 128) return e;
    if (t = 0, this.len - this.pos > 4) {
        for (; t < 5; ++t) if (e.hi = (e.hi | (127 & this.buf[this.pos]) << 7 * t + 3) >>> 0, this.buf[this.pos++] < 128) return e;
    } else for (; t < 5; ++t) {
        if (this.pos >= this.len) throw Error("index out of range");
        if (e.hi = (e.hi | (127 & this.buf[this.pos]) << 7 * t + 3) >>> 0, this.buf[this.pos++] < 128) return e;
    }
    throw Error("invalid varint encoding");
}

// protobufjs's util.merge: Object.keys plus an index loop, NOT for-in.
// (for-in over an `any` receiver is fenced by SC1052; using it here would
// change what this fixture measures.)
function merge(dst, src) {
    for (var a = Object.keys(src), i = 0; i < a.length; ++i) dst[a[i]] = src[a[i]];
    return dst;
}

// `var t = util.Long ? "toLong" : "toNumber"` -- a closure string, not a
// literal at the call site. Both spellings are kept so the fixture pins the
// 0 AND the NaN.
var KEY_LONG = "toLong";
var KEY_NUM = "toNumber";

merge(R.prototype, {
    uint64Long: function () { return p.call(this)[KEY_LONG](true); },
    uint64Num: function () { return p.call(this)[KEY_NUM](true); },
});

// the STATIC-name controls: identical bodies, the name written literally
R.prototype.uint64LongStatic = function () { return p.call(this).toLong(true); };
R.prototype.uint64NumStatic = function () { return p.call(this).toNumber(true); };

// the reader's own answer, read off the LongBits fields with no method
// call at all -- the control that exonerates readLongVarint
R.prototype.rawbits = function () {
    var b = p.call(this);
    return String(b.lo) + ":" + String(b.hi);
};

// exact base-10 of a 64-bit value held as two 32-bit halves, by long
// division in base 10 -- never touches a double, so a value above 2^53
// prints its real decimal.
function u64dec(hi, lo) {
    var d = [0], pass, w, bit, i, carry, cur;
    for (pass = 0; pass < 2; pass++) {
        w = pass === 0 ? hi : lo;
        for (bit = 31; bit >= 0; bit--) {
            carry = (w >>> bit) & 1;
            for (i = 0; i < d.length; i++) {
                cur = d[i] * 2 + carry;
                d[i] = cur % 10;
                carry = Math.floor(cur / 10);
            }
            while (carry > 0) { d.push(carry % 10); carry = Math.floor(carry / 10); }
        }
    }
    var s = "";
    for (i = d.length - 1; i >= 0; i--) s += String(d[i]);
    return s;
}

function fmtLong(o) {
    return u64dec(o.high >>> 0, o.low >>> 0) +
        " (low=" + String(o.low) + " high=" + String(o.high) + " unsigned=" + String(o.unsigned) + ")";
}

// ---- 4111: the varint itself ----
exports.rawbits = function (bytes) { return String(new R(bytes).rawbits()); };
exports.u64Computed = function (bytes) { return fmtLong(new R(bytes).uint64Long()); };
exports.u64Static = function (bytes) { return fmtLong(new R(bytes).uint64LongStatic()); };
exports.u64NumComputed = function (bytes) { return String(new R(bytes).uint64Num()); };
exports.u64NumStatic = function (bytes) { return String(new R(bytes).uint64NumStatic()); };

// ---- 4112: the receiver axes, one construct per row ----
function s(x) { return String(x); }
LB.prototype.thisTag = function () {
    if (this === undefined) return "undefined";
    if (this === null) return "null";
    if (this.lo === undefined) return "an-object-without-lo";
    return "self lo=" + String(this.lo) + " hi=" + String(this.hi);
};
var KEY_TAG = "thisTag";

// the key is a module-scope closure string (protobufjs's own shape)
exports.axClosureKey = function () { var b = new LB(5, 7); return s(b[KEY_TAG]()); };
// the key is a LOCAL
exports.axLocalKey = function () { var k = "thisTag"; var b = new LB(5, 7); return s(b[k]()); };
// the key is a string LITERAL in subscript position
exports.axLiteralSubscript = function () { var b = new LB(5, 7); return s(b["thisTag"]()); };
// the receiver is a CALL RESULT, as in `p.call(this)[t](..)`
function mkbits() { return new LB(5, 7); }
exports.axCallResult = function () { return s(mkbits()[KEY_TAG]()); };
// the same expression reached from inside a METHOD -- before the fix this
// row and axClosureKey disagreed, because the receiver that leaked in was
// the ENCLOSING function's `this`
R.prototype.fromMethod = function () { var b = new LB(5, 7); return b[KEY_TAG](); };
exports.axFromMethod = function () { return s(new R([1, 2, 3]).fromMethod()); };
// the dot spelling: the control that was always right
exports.axDotName = function () { var b = new LB(5, 7); return s(b.thisTag()); };
// read the member out, then call it with an explicit receiver: also always
// right, and the proof that the FUNCTION VALUE the keyed read produces is
// correct and only the binding was missing
exports.axTwoStep = function () { var b = new LB(5, 7); var f = b[KEY_TAG]; return s(f.call(b)); };
// the member read on its own -- `typeof` says the prototype walk finds it
exports.axTypeofMember = function () { var b = new LB(5, 7); return typeof b[KEY_TAG]; };
// an OWN (non-prototype) function member on a CONSTRUCTED object, keyed
// spelling -- scr_dyn_invoke's own-member arm reached through the subscript.
//
// Deliberately NOT an object literal: a literal with heterogeneous field
// types lowers to a typed RECORD, whose function-field call drops the
// receiver through a different path entirely (a separate, pre-existing bug
// -- `o.m()` on such a literal reports `this === undefined` on this tree
// both before and after this change). Mixing that in would make this
// fixture fail for two reasons and pin neither.
function Own() {
    this.lo = 9;
    this.hi = 0;
    this.m = function () { return "self lo=" + String(this.lo) + " hi=" + String(this.hi); };
}
var KEY_M = "m";
exports.axOwnMember = function () { return s(new Own()[KEY_M]()); };
